<template><view class="ui11-page"><view class="ui11-nav"><navigator open-type="navigateBack" class="ui11-nav__back">‹</navigator><text class="ui11-nav__title">记录运动</text><text class="ui11-nav__placeholder"></text></view><view class="form"><view class="ui11-row"><text class="ui11-row__label">运动项目</text><input v-model="form.activity" class="ui11-input" placeholder="例如：走路（快）"/></view><view class="ui11-row"><text class="ui11-row__label">运动时长</text><input v-model="form.durationMinutes" class="ui11-input" type="number" placeholder="分钟"/></view><view class="ui11-row"><text class="ui11-row__label">消耗热量</text><input v-model="form.calories" class="ui11-input" type="number" placeholder="千卡"/></view></view><view class="ui11-fixed-action"><view class="ui11-primary-btn" @click="submit">{{loading?'保存中…':'完成'}}</view></view></view></template>
<script>import { saveExercise } from '@/api/health.js'; export default {data(){return{loading:false,form:{activity:'',durationMinutes:'',calories:''}}},methods:{submit(){if(!this.form.activity)return uni.showToast({title:'请填写运动项目',icon:'none'});this.loading=true;saveExercise(this.form).then(()=>uni.showToast({title:'保存成功',icon:'success'})).catch(()=>uni.showToast({title:'健康服务暂未接入',icon:'none'})).finally(()=>this.loading=false)}}}</script>
<style lang="scss" scoped>.form{padding:0 12rpx;background:#fff}.ui11-input{flex:1;text-align:right;font-size:30rpx}</style>
